When I load and inference a model, it runs slow at first time, but  returns to normal speed after first time.
Is it normal for libtorch or I miss something basic?
I use win10+libtorch1.5+cuda10.1+vs2017
code:
void f()
{
clock_t t1, t2, t3;
t1 = clock();
torch::jit::script::Module model = torch::jit::load("E:/python/pytorch/model.pt");;
model.eval();
model.to(torch::kCUDA);
t2 = clock();
printf("load time : %f ms\n", (double)(t2 - t1) * 1000 / CLOCKS_PER_SEC);
vectortorch::jit::IValue inputs;
torch::Tensor t = torch::ones({ 1,3,127,127 });
inputs.push_back(t.to(torch::kCUDA));
auto out_tensor = model.forward(inputs).toTensor().cpu();
t3 = clock();
printf("inference time : %f ms\n\n", (double)(t3 - t2) * 1000 / CLOCKS_PER_SEC);
}
int main()
{
f(); f(); f(); f(); f();
return 0;
}
